  const commit = (next) => {
    options.onUpdate(next);
  };
  const setModel = (index2, ref) => {
    const next = [...sequence()];
    next[index2] = ref;
    commit(next);
  };
  const addFallback = () => {
    commit([...sequence(), { providerId: "", modelId: "" }]);
  };
  const removeFallback = (index2) => {
    if (index2 === 0) return;
    commit(sequence().filter((_, i) => i !== index2));
  };
