// src/ui/views/SetupWizard/steps/ProviderStep.ts
function ProviderStep({ state, adapter }) {
  const enriched = state;
  const cloneProbe = () => ({
    local: { ...state.probe.local, models: [...state.probe.local.models] },
    remote: { ...state.probe.remote, models: [...state.probe.remote.models] }
  });
  const local = reactive({
    draft: { ...state.embedding },
    probe: cloneProbe()
  });
  const syncLocal = () => {
    local.draft = { ...state.embedding };
    local.probe = cloneProbe();
  };
  const capabilities = () => {
    const caps = enriched.capabilities ?? {
      bootstrap: { mode: "manual", canInstall: false, canRecheck: true },
      embedding: {
        canProbe: true,
        canReadSecretStatus: true,
        canWriteSecrets: true,
        supportedModes: ["local", "remote", "both", "skip"],
        supportsDualProviderFallback: true,
        supportsSelectableOrder: false,
        bothPrimary: "remote"
      },
      connection: {
        canPersistEndpoint: true,
        canWriteBridgeToken: true,
        canClearBridgeToken: false
      },
      configuration: {
        canPatch: true,
        canManageCollections: true,
        canManageInjectors: true,
        canManageIdentities: true,
        canWriteModelRouter: true
      },
      actions: { canToggleWatcher: true, canReindex: true },
      folders: { canList: true, canCreate: true }
    };
    return { embedding: caps.embedding };
  };
  const options = {
    draft: () => local.draft,
    capabilities,
    probeState: () => local.probe,
    secretStatus: () => state.secretStatus,
    onChange: (patch) => {
      updateSetupEmbedding(state, patch);
      syncLocal();
    },
    onProbe: async (target) => {
      const pending = probeSetupEmbedding(state, target, adapter);
      syncLocal();
      await pending;
      syncLocal();
    }
  };
  return html`<div class="oas-setup-step">
		${EmbeddingProviderSection(options)}
	</div>`;
}

