// src/ui/views/SetupWizard/steps/RuntimeStep.ts
function RuntimeStep({
  state,
  local,
  onStart,
  onRecheck
}) {
  const isReady = () => state.runtime.phase === "ready" && state.runtime.serverReachable;
  const isMissing = () => state.runtime.phase === "missing" || state.runtime.phase === "error";
  const isChecking = () => state.runtime.phase === "checking" || local.rechecking;
  const runtimeStatus = () => {
    void local.rechecking;
    if (isChecking()) {
      const isStarting = local.started;
      return Card({
        tone: "running",
        icon: "loader",
        spinIcon: true,
        title: isStarting ? "Starting Bridge\u2026" : "Detecting Agent Runtime\u2026",
        body: html`<p style="color: var(--text-muted);">${isStarting ? "Installing extensions and starting the bridge server\u2026" : "Looking for the agent runtime on your system\u2026"}</p>`
      });
    }
    if (isReady()) {
      return Card({
        tone: "done",
        icon: "check-circle",
        title: "Agent Runtime Found",
        body: html`<div class="oas-flex oas-flex-col oas-gap-1">
					<p style="color: var(--text-success);">Agent runtime detected. Extensions will be installed and the bridge will start when you continue.</p>
					${() => state.runtime.piVersion ? html`<p style="color: var(--text-muted); font-size: var(--font-small);">pi ${state.runtime.piVersion} · extension ${state.runtime.extensionVersion}${state.runtime.piBinaryPath ? ` \xB7 ${state.runtime.piBinaryPath}` : ""}</p>` : ""}
				</div>`
      });
    }
    const message = state.runtime.message ?? "Agent runtime is not available.";
    const isNotFound = /not found/i.test(message);
    return Card({
      tone: isMissing() ? "pending" : "error",
      icon: isMissing() ? "alert-circle" : "x-circle",
      title: isNotFound ? "Runtime not found" : "Runtime found \u2014 bridge not ready",
      body: html`<div class="oas-flex oas-flex-col oas-gap-2">
				<p style="color: var(--text-muted);">${message.replace(/\bpi\b/gi, "Agent runtime")}</p>
				<div class="oas-flex oas-flex-row oas-gap-2">
					${Button({
        label: "Start",
        icon: "play",
        variant: "cta",
        disabled: () => local.rechecking,
        onClick: () => void onStart?.()
      })}
					${Button({
        label: "Recheck",
        icon: "refresh-cw",
        variant: "ghost",
        disabled: () => local.rechecking,
        onClick: () => void onRecheck?.()
      })}
				</div>
			</div>`
    });
  };
  return html`<div class="oas-setup-step">
		<h2 class="setting-item-heading">Welcome to Vault Mind</h2>
		<div class="setting-item-description">Vault Mind connects your Obsidian vault to AI. First we detect the agent runtime, then install extensions and start the bridge.</div>
		${() => runtimeStatus()}
	</div>`;
}

// src/ui/views/SetupWizard/Wizard.ts
var WIZARD_STEPS2 = [
  "runtime",
  "install",
  "provider",
  "folders",
  "preferences",
  "configuration",
  "review",
  "done"
];
var STEP_LABELS = {
  runtime: "Welcome",
  install: "Install extensions",
  provider: "Embedding provider",
  folders: "Vault Locations",
  preferences: "Preferences",
  configuration: "Configuration",
  review: "Review",
  done: "Complete"
};
function startInstallProgress(onProgress) {
  const duration = 1800;
  const start = Date.now();
  let clearPendingTimer = () => {
  };
  const tick = () => {
    const elapsed = Date.now() - start;
    const value = Math.min(elapsed / duration, 0.95);
    onProgress(value);
    if (value < 0.95) {
      const timer = setTimeout(tick, 50);
      clearPendingTimer = () => clearTimeout(timer);
    }
  };
  tick();
  return () => clearPendingTimer();
}
function willInstall2(item) {
  return !item.optional || !!item.confirmed;
}
function countQueuedInstallItems(items) {
  return items.filter((item) => item.kind === "pi" && willInstall2(item)).length;
}
function buildInstallRequest(items) {
  return {
    requiredPackageIds: items.filter((item) => item.kind === "pi" && !item.optional).map((item) => item.id),
    optionalPackageIds: items.filter((item) => item.kind === "pi" && item.optional && willInstall2(item)).map((item) => item.id)
  };
}
function reconcileInstallItems(items, installedPackageIds) {
  const installed = new Set(installedPackageIds);
  return items.map((item) => {
    if (item.kind !== "pi" || !item.optional || !item.confirmed) return { ...item };
    return { ...item, outcome: installed.has(item.id) ? "installed" : "skipped" };
  });
}
async function installThenStartRuntime(adapter, request) {
  const install = await adapter.installRuntime(request);
  if (!install.ok) return { install, runtime: install.runtime };
  return { install, runtime: await adapter.startRuntime() };
}
function isRecord6(value) {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
function applyLoadedState(state, loadRes) {
  const vaultMind = isRecord6(loadRes.config?.config?.vaultMind) ? loadRes.config.config.vaultMind : null;
  const embedding = vaultMind && isRecord6(vaultMind.embedding) ? vaultMind.embedding : null;
  const folders = vaultMind && isRecord6(vaultMind.folders) ? vaultMind.folders : null;
  const vaults = vaultMind && isRecord6(vaultMind.vaults) ? vaultMind.vaults : null;
  const defaultVault = vaults && isRecord6(vaults.default) ? vaults.default : null;
  const extensionCompatibility = isRecord6(loadRes.config?.config?.extensionCompatibility) ? loadRes.config.config.extensionCompatibility : null;
  const piContext = extensionCompatibility && isRecord6(extensionCompatibility["pi-context"]) ? extensionCompatibility["pi-context"] : null;
  if (embedding) {
    const persistedLocalUrl = typeof embedding.localUrl === "string" ? embedding.localUrl : "";
    const persistedRemoteUrl = typeof embedding.remoteUrl === "string" ? embedding.remoteUrl : "";
    const inferredMode = persistedLocalUrl && persistedRemoteUrl ? "both" : persistedRemoteUrl ? "remote" : persistedLocalUrl ? "local" : "skip";
    Object.assign(state.embedding, {
      mode: inferredMode,
      localUrl: persistedLocalUrl || state.embedding.localUrl,
      remoteUrl: persistedRemoteUrl,
      model: typeof embedding.model === "string" ? embedding.model : state.embedding.model,
      dim: typeof embedding.dim === "number" || embedding.dim === null ? embedding.dim : state.embedding.dim
    });
  }
  if (folders) {
    Object.assign(state.folders, {
      inbox: typeof folders.inbox === "string" ? folders.inbox : state.folders.inbox,
      library: typeof folders.library === "string" ? folders.library : state.folders.library,
      presentations: typeof folders.presentations === "string" ? folders.presentations : state.folders.presentations,
      journal: typeof folders.journal === "string" ? folders.journal : state.folders.journal,
      collectionPrefix: typeof folders.collectionPrefix === "string" ? folders.collectionPrefix : state.folders.collectionPrefix,
      canvasPath: typeof folders.canvasPath === "string" ? folders.canvasPath : state.folders.canvasPath
    });
  }
  state.folderOptions = [...loadRes.folders];
  state.secretStatus = loadRes.embeddingSecrets;
  if (defaultVault && typeof defaultVault.autoStart === "boolean") {
    state.preferences.autoStart = defaultVault.autoStart;
  }
  if (defaultVault && typeof defaultVault.autoSync === "boolean") {
    state.preferences.autoSync = defaultVault.autoSync;
  }
  if (defaultVault && typeof defaultVault.autoSyncMinLength === "number") {
    state.preferences.autoSyncMinLength = defaultVault.autoSyncMinLength;
  }
  if (piContext && typeof piContext.enabled === "boolean") {
    state.preferences.contextAutomation = piContext.enabled;
  }
}
function Wizard({
  state,
  adapter,
  onOpenChat,
  local: localOption
}) {
  const initialLocal = localOption ?? {
    started: false,
    rechecking: false,
    installItems: DEFAULT_ITEMS.map((item) => ({ ...item })),
    installProgress: 0,
    installing: false
  };
  const local = reactive(initialLocal);
  const isReady = () => isRuntimeReady(state);
  const isMissing = () => state.runtime.phase === "missing" || state.runtime.phase === "error";
  const isBusy = () => state.savePhase === "saving" || state.savePhase === "verifying";
  const currentIndex = () => WIZARD_STEPS2.indexOf(state.step);
  const isManagedInstall = () => {
    const bootstrap = state.capabilities?.bootstrap;
    return bootstrap?.mode === "managed" && bootstrap?.canInstall;
  };
  const recheck = async () => {
    local.rechecking = true;
    state.runtime = { ...state.runtime, phase: "checking" };
    try {
      state.runtime = await adapter.recheckRuntime();
    } finally {
      local.rechecking = false;
    }
  };
  const refreshLoadedState = async () => {
    try {
      applyLoadedState(state, await adapter.loadConfiguration());
    } catch {
    }
  };
  const startRuntime = async () => {
    local.rechecking = true;
    local.started = true;
    state.runtime = { ...state.runtime, phase: "checking" };
    try {
      state.runtime = await adapter.startRuntime();
      if (state.runtime.phase === "ready") {
        await refreshLoadedState();
      }
    } catch (err) {
      state.runtime = {
        phase: "error",
        piVersion: null,
        extensionVersion: null,
        piBinaryPath: null,
        serverReachable: false,
        message: err instanceof Error ? err.message : String(err)
      };
    } finally {
      local.rechecking = false;
      local.started = false;
    }
  };
  const installRuntime = async () => {
    if (local.installing || state.install === "ready") return;
    state.install = "loading";
    local.installing = true;
    local.installProgress = 0;
    const cancelProgress = startInstallProgress((value) => {
      local.installProgress = value;
    });
    try {
      const result = await installThenStartRuntime(
        adapter,
        buildInstallRequest(local.installItems)
      );
      state.runtime = result.runtime;
      if (result.install.ok) {
        state.install = "ready";
        local.installItems = reconcileInstallItems(
          local.installItems,
          result.install.installedPackageIds
        );
        local.installProgress = 1;
        if (isRuntimeReady(state)) await refreshLoadedState();
      } else {
        state.install = "error";
      }
    } catch {
      state.install = "error";
    } finally {
      cancelProgress();
      local.installing = false;
    }
  };
  const primaryAction = () => {
    const step = state.step;
    if (step === "runtime") {
      void local.rechecking;
      if (isReady()) {
        return {
          label: "Continue",
          icon: "arrow-right",
          disabled: false,
          onClick: () => nextSetupWizard(state)
        };
      }
      if (isManagedInstall() && isMissing()) {
        return {
          label: "Continue",
          icon: "arrow-right",
          disabled: false,
          onClick: () => nextSetupWizard(state, { managedInstallAllowed: true })
        };
      }
      return { label: "Continue", icon: "arrow-right", disabled: true, onClick: () => {
      } };
    }
    if (step === "install") {
      void local.installing;
      if (state.install === "ready") {
        if (isInstallReady(state)) {
          return {
            label: "Continue",
            icon: "arrow-right",
            disabled: false,
            onClick: () => nextSetupWizard(state)
          };
        }
        return {
          label: local.rechecking ? "Checking runtime\u2026" : "Recheck runtime",
          icon: "refresh-cw",
          disabled: local.rechecking,
          onClick: () => void recheck()
        };
      }
      if (isManagedInstall()) {
        const queued = countQueuedInstallItems(local.installItems);
        return {
          label: local.installing ? "Installing\u2026" : `Install ${queued} package${queued !== 1 ? "s" : ""}`,
          icon: "download",
          disabled: local.installing || queued === 0,
          onClick: () => void installRuntime()
        };
      }
      return {
        label: "Continue",
        icon: "arrow-right",
        disabled: !isReady(),
        onClick: () => nextSetupWizard(state, { requiredExtensionsDetected: true })
      };
    }
    if (step === "review") {
      return {
        label: state.savePhase === "error" ? "Retry save" : "Save setup",
        icon: "save",
        disabled: isBusy(),
        onClick: () => void saveSetupWizard(state, adapter)
      };
    }
    if (step === "done") {
      return {
        label: "Open Chat",
        icon: "message-square",
        disabled: false,
        onClick: onOpenChat
      };
    }
    return {
      label: "Continue",
      icon: "arrow-right",
      disabled: false,
      onClick: () => nextSetupWizard(state)
    };
  };
  const showNavPrimary = () => {
    void local.installing;
    return state.step !== "review" && state.step !== "done";
  };
  const showSave = () => state.step === "review";
  const showOpenChat = () => state.step === "done";
  return html`<div class="oas-wizard oas-shell-view">
		<div class="oas-shell-view-header oas-wizard-header">
			<div class="oas-wizard-identity">
				${icon("folder")}
				<span class="oas-wizard-title">Vault Mind</span>
			</div>
			${() => state.step !== "runtime" ? html`<div class="oas-wizard-step-info">
						<div class="oas-wizard-step-name">${() => STEP_LABELS[state.step]}</div>
						<div class="oas-text-muted">${() => `${currentIndex() + 1} of ${WIZARD_STEPS2.length}`}</div>
					</div>` : ""}
			<div class="oas-wizard-progress">
				${WIZARD_STEPS2.map(
    (_s, i) => html`<span class="${() => currentIndex() >= i ? "oas-wizard-dot is-active" : "oas-wizard-dot"}"></span>`
  )}
			</div>
		</div>
		<div class="oas-shell-view-body oas-wizard-body">
			${() => state.step === "runtime" ? RuntimeStep({ state, local, onStart: startRuntime, onRecheck: recheck }) : ""}
			${() => state.step === "install" ? InstallStep({ state, local, onStart: startRuntime, onRecheck: recheck }) : ""}
			${() => state.step === "provider" ? ProviderStep({ state, adapter }) : ""}
			${() => state.step === "folders" ? FoldersStep({ state, adapter }) : ""}
			${() => state.step === "preferences" ? PreferencesStep({ state }) : ""}
			${() => state.step === "configuration" ? ConfigurationStep({ state, adapter }) : ""}
			${() => state.step === "review" ? ReviewSaveStep({ state, adapter }) : ""}
			${() => state.step === "done" ? DoneStep({ state, onOpenChat }) : ""}
		</div>
		<div class="oas-shell-view-footer oas-wizard-footer">
			<div class="oas-wizard-footer-row">
				<div class="${() => state.step === "runtime" || state.step === "done" ? "oas-wizard-back is-hidden" : "oas-wizard-back"}">
					${Button({
    label: "Back",
    icon: "arrow-left",
    variant: "ghost",
    disabled: () => isBusy(),
    onClick: () => backSetupWizard(state)
  })}
				</div>
				<div class="oas-wizard-footer-actions">
					<div class="${() => showNavPrimary() ? "oas-wizard-footer-action" : "oas-wizard-footer-action is-hidden"}">
						${Button({
    label: () => primaryAction().label,
    icon: "arrow-right",
    variant: "cta",
    disabled: () => primaryAction().disabled || isBusy(),
    onClick: () => {
      const action = primaryAction();
      action.onClick();
    }
  })}
					</div>
					<div class="${() => showSave() ? "oas-wizard-footer-action" : "oas-wizard-footer-action is-hidden"}">
						${Button({
    icon: "bookmark",
    label: () => primaryAction().label,
    variant: "cta",
    disabled: () => primaryAction().disabled || isBusy(),
    onClick: () => {
      const action = primaryAction();
      action.onClick();
    }
  })}
					</div>
					<div class="${() => showOpenChat() ? "oas-wizard-footer-action" : "oas-wizard-footer-action is-hidden"}">
						${Button({
    label: "Open Chat",
    icon: "message",
    variant: "cta",
    disabled: () => false,
    onClick: () => onOpenChat()
  })}
					</div>
				</div>
			</div>
		</div>
	</div>`;
}

// src/ui/views/SetupWizard/SetupWizard.ts
function SetupWizard(options) {
  const state = options.state ?? createSetupWizardState(options.vaultPath);
  if (!("vault" in state)) {
    Object.defineProperty(state, "vault", {
      value: options.vaultPath,
      enumerable: false,
      configurable: true,
      writable: true
    });
  }
  return Wizard({
    state,
    adapter: options.adapter,
    onOpenChat: options.onOpenChat,
    local: options.local
  });
}

// src/ui/integrations/VaultMindView/VaultMindPanel.ts
var import_obsidian5 = require("obsidian");

// src/model-utils.ts
var KNOWN_EMBEDDING_MODELS = [
  "embeddinggemma",
  "nomic-embed-text",
  "mxbai-embed-large",
  "all-minilm",
  "paraphrase-multilingual"
];
function getModelCapabilities(model) {
  const explicitChat = model.capabilities?.chat;
  const explicitEmbedding = model.capabilities?.embedding;
  if (typeof explicitChat === "boolean" || typeof explicitEmbedding === "boolean") {
    const embedding2 = typeof explicitEmbedding === "boolean" ? explicitEmbedding : false;
    return {
      chat: typeof explicitChat === "boolean" ? explicitChat : !embedding2,
      embedding: embedding2
    };
  }
  const id = model.id.toLowerCase();
  const knownModel = KNOWN_EMBEDDING_MODELS.some((name) => id.includes(name));
  const embeddingFamily = /(^|[/_:.-])(?:bge-|embed(?:ding)?(?:$|[/_:.-]))/.test(id);
  const embedding = knownModel || embeddingFamily;
  return { chat: !embedding, embedding };
}

// src/ui/components/Suggest/Suggest.ts
function Suggest(o) {
  return Popover({
    isOpen: o.isOpen,
    onDismiss: o.onDismiss,
    position: {
      mode: "caret",
      point: () => {
        const ta = o.textarea();
        return ta ? caretPoint(ta) : { top: 0, left: 0 };
      }
    },
    header: o.header,
    width: o.width,
    rootClass: "oas-suggest",
    variant: {
      kind: "list",
      items: o.items,
      key: (i) => i,
      label: (i) => o.renderItem ? o.renderItem(i) : i,
      onSelect: o.onSelect,
      emptyText: o.emptyText ?? "No matches"
    }
  });
}

// src/ui/components/OmniComposer/OmniComposer.ts
function OmniComposer(o) {
  const triggers = o.triggers ?? [];
  const s = reactive({ active: -1, query: "" });
  let textareaEl = null;
  const captureEl = (e) => {
    textareaEl = e.target;
  };
  const grow = () => {
    if (!textareaEl) return;
    textareaEl.style.height = "auto";
    textareaEl.style.height = `${textareaEl.scrollHeight}px`;
  };
  const close = () => {
    s.active = -1;
  };
  const detectTriggers = () => {
    const ta = textareaEl;
    if (!ta) {
      s.active = -1;
      return;
    }
    const caret = ta.selectionStart ?? 0;
    const val = ta.value;
    for (let i = 0; i < triggers.length; i++) {
      const t = triggers[i];
      if (!t.atLineStart) continue;
      if (caret === val.length && val.startsWith(t.char) && !/\s/.test(val.slice(t.char.length))) {
        s.active = i;
        s.query = val.slice(t.char.length);
        return;
      }
    }
    const lastWord = val.slice(0, caret).split(/\s/).pop() ?? "";
    for (let i = 0; i < triggers.length; i++) {
      const t = triggers[i];
      if (t.atLineStart) continue;
      if (lastWord.startsWith(t.char)) {
        s.active = i;
        s.query = lastWord.slice(t.char.length);
        return;
      }
    }
    s.active = -1;
  };
  const stripToken = (char) => {
    const escaped = char.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const next = o.value().replace(new RegExp(`${escaped}\\S*$`), "").replace(/\s+$/, "");
    o.onInput(next);
    if (textareaEl) {
      textareaEl.value = next;
      textareaEl.focus();
    }
  };
  const selectItem = (i, item) => {
    const t = triggers[i];
    t.onSelect(item);
    if (t.stripTokenOnSelect !== false) stripToken(t.char);
    else if (textareaEl) {
      textareaEl.value = o.value();
      textareaEl.focus();
    }
    close();
  };
  const runChipAction = () => {
    const a = o.chipAction;
    if (!a) return;
    if (!a.triggerChar) {
      a.onClick?.();
      return;
    }
    const idx = triggers.findIndex((t) => t.char === a.triggerChar);
    if (idx < 0) return;
    if (s.active === idx) return;
    if (!textareaEl) textareaEl = document.querySelector(".oas-omni-textarea");
    const val = o.value();
    const needsSpace = val.length > 0 && !val.endsWith(" ");
    const next = `${val}${needsSpace ? " " : ""}${a.triggerChar}`;
    o.onInput(next);
    s.active = idx;
    s.query = "";
    if (textareaEl) {
      textareaEl.value = next;
      textareaEl.focus();
    }
  };
  const handleInput = (e) => {
    captureEl(e);
    o.onInput(e.target.value);
    grow();
    detectTriggers();
  };
  const handleKeydown = (e) => {
    const ke = e;
    if (s.active !== -1) {
      if (ke.key === "Enter" || ke.key === "Escape") {
        e.preventDefault();
        if (ke.key === "Escape") close();
      }
      return;
    }
    if (ke.key === "Enter" && !ke.shiftKey && (o.submitOnEnter ?? true)) {
      e.preventDefault();
      o.onSubmit?.(o.value());
    }
  };
  return html`<div class="oas-omni-stack">
		${() => o.above ?? ""}
		<div class="oas-omni">
			${() => o.chips || o.chipAction ? html`<div class="oas-omni-header">
							<div class="oas-omni-chips">${() => o.chips ?? ""}</div>
							${o.chipAction ? Button({
    label: o.chipAction.label,
    icon: o.chipAction.icon,
    variant: "ghost",
    onClick: runChipAction
  }) : ""}
						</div>` : ""}
			<div class="oas-omni-input">
				<textarea
					class="oas-omni-textarea"
					rows="1"
					placeholder="${() => o.placeholder?.() ?? ""}"
					@focus="${captureEl}"
					@input="${handleInput}"
					@keydown="${handleKeydown}"
					.value="${() => o.value()}"
				></textarea>
				${triggers.map(
    (t, i) => Suggest({
      isOpen: () => s.active === i,
      onDismiss: close,
      textarea: () => textareaEl,
      items: () => t.items(s.query),
      onSelect: (item) => selectItem(i, item),
      header: t.header,
      renderItem: t.renderItem,
      emptyText: t.emptyText
    }).key(t.char)
  )}
			</div>
			${() => o.footer ? html`<div class="oas-omni-footer">${() => o.footer}</div>` : ""}
		</div>
	</div>`;
}

