// src/ui/views/VaultMindView/SearchView/SearchView.ts
function SearchView(o) {
  const root = () => document.querySelector(`[data-search-list="${o.listId}"]`);
  const rebuild = () => {
    const el = root();
    const groups = el?.querySelector(".oas-search-groups");
    const presearch = el?.querySelector(".oas-search-presearch");
    const noresults = el?.querySelector(".oas-search-noresults");
    if (!el || !groups) return;
    const hits = o.results();
    const searched = o.hasSearched();
    presearch?.classList.toggle("is-hidden", searched);
    noresults?.classList.toggle("is-hidden", !(searched && hits.length === 0));
    groups.textContent = "";
    for (const source of SOURCE_ORDER) {
      const sourceHits = hits.filter((h) => h.source === source);
      if (sourceHits.length === 0) continue;
      const group = document.createElement("div");
      group.className = "oas-search-group";
      groups.appendChild(group);
      const labelSlot = document.createElement("div");
      group.appendChild(labelSlot);
      SectionLabel(`${SOURCE_LABEL[source]} \xB7 ${sourceHits.length}`)(labelSlot);
      for (const hit of sourceHits) {
        const slot = document.createElement("div");
        group.appendChild(slot);
        ResultRow({ hit, onOpen: o.onOpenHit })(slot);
      }
    }
  };
  watch(
    () => `${o.hasSearched()}|${JSON.stringify(o.results())}`,
    () => {
      window.setTimeout(rebuild, 0);
    }
  );
  const init = (attemptsLeft) => {
    if (root()) {
      rebuild();
      return;
    }
    if (attemptsLeft > 0) window.setTimeout(() => init(attemptsLeft - 1), 50);
  };
  window.setTimeout(() => init(30), 0);
  return html`<div class="oas-search-view">
		<div class="oas-search-view-composer">
			${SearchComposer({
    query: o.query,
    onQuery: o.onQuery,
    sources: o.sources,
    onToggleSource: o.onToggleSource,
    mode: o.mode,
    onMode: o.onMode
  })}
		</div>
		<div class="oas-search-view-results" data-search-list="${o.listId}">
			<div class="oas-search-presearch">
				${EmptyState({
    icon: "search",
    title: "Search everything",
    description: "Your vault, past sessions, and this conversation. Choose sources below."
  })}
			</div>
			<div class="oas-search-noresults is-hidden">
				${EmptyState({
    icon: "search",
    title: "No matches",
    description: "Try a different query, widen the scope, or switch the mode."
  })}
			</div>
			<div class="oas-search-groups"></div>
		</div>
	</div>`;
}

